namespace Voyara.Domain.Enums;

/// <summary>
/// Identifies the authoring role of a message in an AI assistant conversation session.
/// </summary>
public enum MessageRole
{
    /// <summary>
    /// Message authored by the human end user or tourist.
    /// </summary>
    User,

    /// <summary>
    /// Message generated by the AI assistant or travel planner agent.
    /// </summary>
    Assistant,

    /// <summary>
    /// System prompt, context injection, or platform instructions directing conversational behavior.
    /// </summary>
    System
}

